        static bool TryNamespaceTextSlot(object? value, string name, out object? callable)
        {
            if (value is PyLocalClassInstance local && local.PythonType.TryLookup(name, out var member))
            {
                callable = PyMetaclasses.Bind(member, local, local.PythonType);
                return true;
            }
            var (owner, inherited) = LookupSourceSpecialMethod(value, name, dataOnly: true);
            callable = inherited;
            return owner != null;
        }

        static string InvokeTextSlot(object? callable, string name) => (object?)__invoke(callable, []) as string ??
            throw new InvalidCastException($"{name} returned a non-string value");

        static bool TryInstanceString(object? value, out string text)
        {
            if (TryNamespaceTextSlot(value, "__str__", out var strMethod))
            {
                text = InvokeTextSlot(strMethod, "__str__");
                return true;
            }
            if (TryNamespaceTextSlot(value, "__repr__", out var reprMethod))
            {
                var (owner, declared) = LookupSourceSpecialMethod(value, "__str__");
                text = owner == null ? InvokeTextSlot(reprMethod, "__repr__") : InvokeTextSlot(declared, "__str__");
                return true;
            }
            text = "";
            return false;
        }

        internal static string DefaultClassRepr(Type type) => $"<class '{PythonQualifiedTypeName(type)}'>";

        static string ClassRepr(Type type) => type == typeof(Typhon.Stdlib._typing.Any) ? "typing.Any" :
            TryMetaclassText(type, "__repr__", out string text) ? text : DefaultClassRepr(type);

        static bool TryMetaclassText(Type type, string slot, out string result)
        {
            result = "";
            if (!PyMetaclasses.TryBindMember(type, slot, out var callable)) return false;
            result = (object?)__invoke(callable, []) as string ??
                throw new InvalidCastException($"{slot} returned a non-string value");
            return true;
        }

        /// <summary>object.__str__ delegates to repr and avoids any overridden __str__.</summary>
        public static string __object_str(object? value)
        {
            if (value == null || value is IPyRepr) return repr(value);
            Type type = value.GetType();
            string module = ModuleOfType(type);
            if (type == typeof(object)) return $"<object object at 0x{id(value):x}>";
            if (module == "builtins") return repr(value);
            string name = PyTypeName(type);
            for (var parent = type.DeclaringType; parent?.DeclaringType != null; parent = parent.DeclaringType)
                name = PyTypeName(parent) + "." + name;
            return $"<{module}.{name} object at 0x{id(value):x}>";
        }

        static string Quote(string s)
        {
            char q = s.Contains('\'') && !s.Contains('"') ? '"' : '\'';
            var sb = new StringBuilder().Append(q);
            for (int index = 0; index < s.Length;)
            {
                bool valid = Rune.TryGetRuneAt(s, index, out Rune rune);
                int codePoint = valid ? rune.Value : s[index];
                int width = valid ? rune.Utf16SequenceLength : 1;
                switch (codePoint)
                {
                    case '\\': sb.Append("\\\\"); break;
                    case '\n': sb.Append("\\n"); break;
                    case '\r': sb.Append("\\r"); break;
                    case '\t': sb.Append("\\t"); break;
                    default:
                        UnicodeCategory category = valid ? Rune.GetUnicodeCategory(rune) : UnicodeCategory.Surrogate;
                        bool printable = codePoint == ' ' || category is not (UnicodeCategory.Control or UnicodeCategory.Format or
                            UnicodeCategory.Surrogate or UnicodeCategory.PrivateUse or UnicodeCategory.OtherNotAssigned or
                            UnicodeCategory.SpaceSeparator or UnicodeCategory.LineSeparator or UnicodeCategory.ParagraphSeparator);
                        if (printable)
                        {
                            if (codePoint == q) sb.Append('\\');
                            sb.Append(s, index, width);
                        }
                        else if (codePoint <= 0xff) sb.Append("\\x").Append(codePoint.ToString("x2", Inv));
                        else if (codePoint <= 0xffff) sb.Append("\\u").Append(codePoint.ToString("x4", Inv));
                        else sb.Append("\\U").Append(codePoint.ToString("x8", Inv));
                        break;
                }
                index += width;
            }
            return sb.Append(q).ToString();
        }

        static string FormatComplex(Complex c)
        {
            static string Component(double n)
            {
                string s = FormatFloat(n);
                return s.EndsWith(".0", StringComparison.Ordinal) ? s[..^2] : s;
            }
            string imag = Component(c.Imaginary);
            if (BitConverter.DoubleToInt64Bits(c.Real) == 0) return imag + "j";
            return $"({Component(c.Real)}{(imag.StartsWith('-') ? "" : "+")}{imag}j)";
        }

        /// <summary>CPython's float repr: shortest round-trip digits, exponent form when the decimal exponent is &lt; -4 or &gt;= 16.</summary>
        static string FormatFloat(double d)
        {
            if (double.IsNaN(d)) return "nan";
            if (double.IsInfinity(d)) return d > 0 ? "inf" : "-inf";
            if (d == 0) return double.IsNegative(d) ? "-0.0" : "0.0";
            var (neg, digits, point) = ShortestDigits(d);
            int exp = point - 1;
            string s;
            if (exp >= 16 || exp < -4)
                s = digits.Substring(0, 1) + (digits.Length > 1 ? "." + digits.Substring(1) : "") + ExpSuffix('e', exp);
            else if (point <= 0) s = "0." + new string('0', -point) + digits;
            else if (point >= digits.Length) s = digits + new string('0', point - digits.Length) + ".0";
            else s = digits.Substring(0, point) + "." + digits.Substring(point);
            return neg ? "-" + s : s;
        }

        /// <summary>Shortest round-trip decimal digits of d (no leading/trailing zeros) and the decimal point position: value = 0.DIGITS * 10^point.</summary>
        static (bool neg, string digits, int point) ShortestDigits(double d)
        {
            string r = d.ToString("R", Inv);
            bool neg = r[0] == '-';
            if (neg) r = r.Substring(1);
            int exp10 = 0, e = r.IndexOfAny(new[] { 'E', 'e' });
            if (e >= 0) { exp10 = int.Parse(r.Substring(e + 1), Inv); r = r.Substring(0, e); }
            int dot = r.IndexOf('.');
            string intPart = dot >= 0 ? r.Substring(0, dot) : r;
            string digits = intPart + (dot >= 0 ? r.Substring(dot + 1) : "");
            int point = intPart.Length + exp10;
            int lead = 0;
            while (lead < digits.Length - 1 && digits[lead] == '0') lead++;
            digits = digits.Substring(lead).TrimEnd('0');
            point -= lead;
            if (digits.Length == 0) { digits = "0"; point = 1; }
            return (neg, digits, point);
        }

        static string ExpSuffix(char e, int exp) => e + (exp < 0 ? "-" : "+") + Math.Abs(exp).ToString("00", Inv);

        /// <summary>Python's 'g' presentation (and the no-type form with a precision when <paramref name="noType"/>): p significant digits,
        /// exponent form when exp &lt; -4 or exp &gt;= p (exp &gt;= p - 1 without a type), trailing zeros removed.</summary>
        static string FormatGeneral(double a, int precision, bool upper, bool noType, bool alternate)
        {
            if (double.IsNaN(a)) return upper ? "NAN" : "nan";
            if (double.IsInfinity(a)) return upper ? "INF" : "inf";
            int p = precision < 0 ? 6 : Math.Max(precision, 1);
            if (a == 0) return noType ? "0.0" : (alternate ? "0." + new string('0', p - 1) : "0");
            string es = a.ToString("E" + (p - 1), Inv);
            int ei = es.IndexOf('E');
            int exp = int.Parse(es.Substring(ei + 1), Inv);
            bool useExp = exp < -4 || exp >= (noType ? p - 1 : p);
            string body;
            if (useExp)
            {
                string mant = es.Substring(0, ei);
                if (!alternate && mant.Contains('.')) mant = mant.TrimEnd('0').TrimEnd('.');
                body = mant + ExpSuffix(upper ? 'E' : 'e', exp);
            }
            else
            {
                body = a.ToString("F" + Math.Max(p - 1 - exp, 0), Inv);
                if (!alternate && body.Contains('.')) body = body.TrimEnd('0').TrimEnd('.');
                if (noType && !body.Contains('.')) body += ".0";
            }
            return body;
        }

        // the generic type definition check works under Native AOT, where GetInterfaces() may not list trimmed interfaces
        static bool IsSet(object o)
        {
            var t = o.GetType();
            if (t.IsGenericType)
            {
                var def = t.GetGenericTypeDefinition();
                if (def == typeof(HashSet<>) || def == typeof(SortedSet<>) || def == typeof(System.Collections.Frozen.FrozenSet<>)) return true;
            }
            return t.GetInterfaces().Any(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(ISet<>));
        }

