                parts.Insert(0, rest.Substring(i + (sep?.Length ?? 1)));
                rest = sep == null ? rest.Substring(0, i).TrimEnd() : rest.Substring(0, i);
            }
            parts.Insert(0, rest);
            return parts;
        }
        public static string removeprefix(this string s, string prefix) => s.StartsWith(prefix, StringComparison.Ordinal) ? s.Substring(prefix.Length) : s;
        public static string removesuffix(this string s, string suffix) => suffix.Length > 0 && s.EndsWith(suffix, StringComparison.Ordinal) ? s.Substring(0, s.Length - suffix.Length) : s;
        public static string swapcase(this string s) => new string(s.Select(c => char.IsUpper(c) ? char.ToLowerInvariant(c) : char.IsLower(c) ? char.ToUpperInvariant(c) : c).ToArray());
        public static string casefold(this string s) => s.ToLowerInvariant();
        public static string expandtabs(this string s, long tabsize = 8)
        {
            var sb = new StringBuilder(); int col = 0;
            foreach (char c in s)
            {
                if (c == '\t') { int n = tabsize > 0 ? (int)(tabsize - col % tabsize) : 0; sb.Append(' ', n); col += n; }
                else { sb.Append(c); col = c == '\n' || c == '\r' ? 0 : col + 1; }
            }
            return sb.ToString();
        }
        public static bool isascii(this string s) => s.All(c => c < 128);
        public static bool isdecimal(this string s) => s.Length > 0 && s.All(c => char.GetUnicodeCategory(c) == UnicodeCategory.DecimalDigitNumber);
        public static bool isnumeric(this string s) => s.Length > 0 && s.All(char.IsNumber);
        public static bool isidentifier(this string s) => s.Length > 0 && (char.IsLetter(s[0]) || s[0] == '_') && s.All(c => char.IsLetterOrDigit(c) || c == '_');
        public static bool isprintable(this string s) => s.All(c => !char.IsControl(c));
        public static bool istitle(this string s)
        {
            bool cased = false, prevCased = false;
            foreach (char c in s)
            {
                if (char.IsUpper(c)) { if (prevCased) return false; prevCased = cased = true; }
                else if (char.IsLower(c)) { if (!prevCased) return false; prevCased = cased = true; }
                else prevCased = false;
            }
            return cased;
        }
        public static List<string> splitlines(this string s, bool keepends)
        {
            if (!keepends) return s.splitlines();
            var r = new List<string>(); int start = 0;
            for (int i = 0; i < s.Length; i++)
            {
                if (s[i] == '\n' || s[i] == '\r')
                {
                    int end = s[i] == '\r' && i + 1 < s.Length && s[i + 1] == '\n' ? i + 2 : i + 1;
                    r.Add(s.Substring(start, end - start)); start = end; i = end - 1;
                }
            }
            if (start < s.Length) r.Add(s.Substring(start));
            return r;
        }
        public static Dictionary<long, string?> maketrans(string from, string to, string? delete = null)
        {
            var d = new Dictionary<long, string?>();
            for (int i = 0; i < from.Length; i++) d[from[i]] = to[i].ToString();
            if (delete != null) foreach (char c in delete) d[c] = null;
            return d;
        }

        public static OrderedDictionary<object, object?> maketrans(IDictionary table)
        {
            var result = __newdict<object, object?>(table.Count);
            foreach (DictionaryEntry entry in table)
            {
                object key = entry.Key;
                if (key is char c) key = (long)c;
                else if (key is string s)
                {
                    if (s.Length == 1) key = (long)s[0];
                    else if (s.Length == 2 && char.IsSurrogatePair(s, 0)) key = (long)char.ConvertToUtf32(s, 0);
                    else throw new ArgumentException("string keys in translatetable must be of length 1");
                }
                else if (key is not BigInteger && !IntLike(key, out _))
                    throw new InvalidCastException("keys in translate table mustbe strings or integers");
                result[key] = entry.Value;
            }
            return result;
        }

        public static OrderedDictionary<object, object?> maketrans(this string _, IDictionary table) => maketrans(table);

        public static string translate(this string s, IDictionary<long, string?> table)
        {
            var sb = new StringBuilder();
            foreach (char c in s) { if (table.TryGetValue(c, out var r)) { if (r != null) sb.Append(r); } else sb.Append(c); }
            return sb.ToString();
        }

        public static string translate(this string s, OrderedDictionary<object, object?> table)
        {
            var sb = new StringBuilder();
            for (int i = 0; i < s.Length;)
            {
                bool surrogatePair = char.IsSurrogatePair(s, i);
                int width = surrogatePair ? 2 : 1;
                long codepoint = surrogatePair ? char.ConvertToUtf32(s, i) : s[i];
                if (!table.TryGetValue(codepoint, out var replacement)) sb.Append(s, i, width);
                else if (replacement is string text) sb.Append(text);
                else if (replacement != null)
                {
                    long number = replacement is BigInteger big ? big >= 0 && big <= 0x10ffff ? (long)big : -1
                        : IntLike(replacement, out long n) ? n : throw new InvalidCastException("character mapping must return integer, None or str");
                    if (number < 0 || number > 0x10ffff) throw new ArgumentException("character mapping must be in range(0x110000)");
                    if (number <= char.MaxValue) sb.Append((char)number);
                    else sb.Append(char.ConvertFromUtf32((int)number));
                }
                i += width;
            }
            return sb.ToString();
        }
        public static long rfind(this string s, string sub) => s.LastIndexOf(sub, StringComparison.Ordinal);
        /// <summary>s.rfind(sub, start[, end]) / s.rindex over s[start:end] (an empty sub is found at the end).</summary>
        public static long rfind(this string s, string sub, long start, long? end = null)
        {
            var (a, b) = StringSearchBounds(s.Length, start, end);
            if (b < a) return -1;
            if (sub.Length == 0) return b;
            if (b - a < sub.Length) return -1;
            int i = s.LastIndexOf(sub, b - 1, b - a, StringComparison.Ordinal);
            return i >= 0 && i + sub.Length <= b ? i : -1;
        }
        public static long rfind(this string s, string sub, object? start, object? end = null)
        {
            var (first, last, _) = new PySlice(start, end).Bounds();
            return s.rfind(sub, first ?? 0, last);
        }
        public static long rindex(this string s, string sub, long start, long? end = null) { long i = s.rfind(sub, start, end); return i >= 0 ? i : throw new ArgumentException("substring not found"); }
        public static long rindex(this string s, string sub, object? start, object? end = null) { long i = s.rfind(sub, start, end); return i >= 0 ? i : throw new ArgumentException("substring not found"); }
        public static long index(this string s, string sub) { int i = s.IndexOf(sub, StringComparison.Ordinal); return i >= 0 ? i : throw new ArgumentException("substring not found"); }
        public static long count(this string s, string sub) => s.count(sub, 0);
        public static bool isdigit(this string s) => s.Length > 0 && s.All(char.IsDigit);
        public static bool isalpha(this string s) => s.Length > 0 && s.All(char.IsLetter);
        public static bool isalnum(this string s) => s.Length > 0 && s.All(char.IsLetterOrDigit);
        public static bool isspace(this string s) => s.Length > 0 && s.All(char.IsWhiteSpace);
        public static bool isupper(this string s) => s.Any(char.IsLetter) && !s.Any(char.IsLower);
        public static bool islower(this string s) => s.Any(char.IsLetter) && !s.Any(char.IsUpper);
        public static string title(this string s) => CultureInfo.InvariantCulture.TextInfo.ToTitleCase(s.ToLowerInvariant());
        public static string capitalize(this string s) => s.Length == 0 ? s : char.ToUpperInvariant(s[0]) + s.Substring(1).ToLowerInvariant();
        public static string zfill(this string s, object? width)
        {
            long size = StringSize(width);
            if (size <= s.Length) return s;
            return s.Length > 0 && s[0] is '+' or '-'
                ? s[0] + s.Substring(1).PadLeft(Width(size - 1), '0')
                : s.PadLeft(Width(size), '0');
        }
        public static string center(this string s, long width, string fill = " ") => format(s, fill + "^" + Width(width));
        public static string center(this string s, object? width, string fill = " ") => s.center(StringSize(width), fill);
        public static PyBytes ljust(this PyBytes value, long width, PyBytes? fillbyte = null) => value.ljust(width, fillbyte);
        public static PyByteArray ljust(this PyByteArray value, long width, PyBytes? fillbyte = null) => value.ljust(width, fillbyte);
        public static string ljust(this string s, long width, string fill = " ") => s.PadRight(Width(width), fill[0]);
        public static string ljust(this string s, object? width, string fill = " ") => s.ljust(StringSize(width), fill);
        public static string rjust(this string s, long width, string fill = " ") => s.PadLeft(Width(width), fill[0]);
        public static string rjust(this string s, object? width, string fill = " ") => s.rjust(StringSize(width), fill);
        static int Width(long w) => w <= 0 ? 0 : checked((int)w);

